"""Sanitize recorded native observations and recompute aggregate usage."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent
FILES = ("journal.py", "planner.py", "policy.py", "release.py")
WINDOWS = re.compile(r"(?i)\b[CG]:[/\\]+(?:Users|CodexProjects|CodexArchive)(?:[/\\]+[^\s`'\"<>,;]*)?")
WSL = re.compile(r"(?i)(?<![\w/])/mnt/[cg]/(?:Users|CodexProjects|CodexArchive)(?:/[^\s`'\"<>,;]*)?")
SECRET = re.compile(r"(?i)\b(?:sk|ds|ghp|github_pat)-[A-Za-z0-9_-]{12,}|([?&]token=)[^\s`'\"]+")


ENV_SECRETS = tuple(value for name, value in os.environ.items()
                    if re.search(r"(?i)(?:deepseek|openai|github).*(?:key|token)", name) and len(value) >= 12)


def read(path, default=None):
    if not path.is_file():
        return default
    return json.loads(path.read_text(encoding="utf-8-sig"))


def events(path):
    if not path.is_file():
        return []
    result = []
    for row in path.read_text(encoding="utf-8-sig").splitlines():
        if row.strip():
            try:
                result.append(json.loads(row))
            except json.JSONDecodeError:
                result.append({"type": "incomplete-event-row"})
    return result


def scrub(value):
    if isinstance(value, str):
        for secret in ENV_SECRETS:
            value = value.replace(secret, "[redacted]")
        return SECRET.sub("[redacted]", WSL.sub("[local-path]", WINDOWS.sub("[local-path]", value)))
    if isinstance(value, dict):
        return {key: scrub(item) for key, item in value.items()}
    if isinstance(value, list):
        return [scrub(item) for item in value]
    return value


def usage(rows, window=None):
    grouped = defaultdict(lambda: {"responses": 0, "withUsage": 0, "inputTokens": 0,
                                  "outputTokens": 0, "cacheReadTokens": 0, "cacheWriteTokens": 0,
                                  "totalTokens": 0, "mismatch": 0})
    for row in rows:
        if row.get("type") != "assistant/message" or (window is not None and row.get("window") != window):
            continue
        u = row.get("usage")
        bucket = grouped[(row["mode"], row["stage"], row["role"])]
        bucket["responses"] += 1
        if not u:
            continue
        bucket["withUsage"] += 1
        names = ("inputTokens", "outputTokens", "cacheReadTokens", "cacheWriteTokens")
        for key in (*names, "totalTokens"):
            bucket[key] += u.get(key) or 0
        if sum(u.get(key) or 0 for key in names) != u["totalTokens"]:
            bucket["mismatch"] += 1
    return [{"mode": mode, "stage": stage, "role": role, **value}
            for (mode, stage, role), value in sorted(grouped.items())]


def artifact(path):
    blob = path.read_bytes()
    raw = blob.decode("utf-8", "replace")
    text = scrub(raw)
    item = {"sha256": hashlib.sha256(blob).hexdigest(), "text": text}
    if text != raw:
        item["publishedTextSha256"] = hashlib.sha256(text.encode("utf-8")).hexdigest()
    return item


def receipts(root):
    def identity_fields(value):
        if isinstance(value, dict):
            return {key: hashlib.sha256(item.encode()).hexdigest()[:12]
                    if key in {"actor", "auditor", "reviewer"} and isinstance(item, str)
                    else identity_fields(item) for key, item in value.items()}
        if isinstance(value, list):
            return [identity_fields(item) for item in value]
        return value

    rows = []
    for lane in ("bl", "bl2"):
        for path in sorted((root / "work" / lane / "receipts").glob("*.json")):
            data = read(path, {})
            role = data.get("reviewer") or data.get("auditor")
            payload = {key: data[key] for key in ("unit", "phase", "goal", "candidateSha256", "decision",
                       "codeRegression", "codeReview", "independentAudit") if key in data}
            rows.append({"lane": lane, "name": path.name,
                         "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                         "roleIdentity": hashlib.sha256(role.encode()).hexdigest()[:12] if isinstance(role, str) else None,
                         "receipt": identity_fields(payload)})
    return rows


def scoring(baseline, final):
    before = {case["id"] for case in baseline["cases"] if case["status"] == "passed"}
    after = {case["id"] for case in final["cases"] if case["status"] == "passed"}
    all_previous = {case["id"] for case in baseline["cases"]}
    all_current = {case["id"] for case in final["cases"]}
    new = all_current - all_previous
    return {"retained": len(before & after), "protected": len(before), "newPass": len(new & after), "newTotal": len(new),
            "allPass": len(after), "allTotal": len(all_current),
            "architectureEdges": sum(bool(value.get("boundaryOk")) for value in final["architecture"].values()),
            "architectureIO": sum(bool(value.get("transportOnlyIO")) for value in final["architecture"].values())}


def run(root):
    meta = read(root / "metadata.json", {})
    result = read(root / "result.json", {})
    calls = events(root / "events.jsonl")
    witness = root / "h" / "profiles" / "qa" / "witness.mjs"
    meta["loadedWitnessSha256"] = hashlib.sha256(witness.read_bytes()).hexdigest() if witness.is_file() else None
    completed = []
    for mode in ("standard", "standard-checklist", "building-loop"):
        for stage in ("g1", "g2"):
            item = read(root / (mode + "-" + stage + ".json"))
            if not item:
                continue
            frozen = root / "frozen" / mode / stage
            item["frozenSource"] = {name: artifact(frozen / name) for name in FILES if (frozen / name).is_file()}
            item["frozenHandoff"] = artifact(frozen / "HANDOFF.md") if (frozen / "HANDOFF.md").is_file() else None
            item["score"] = scoring(item["baseline"], item["final"])
            comparison = item.get("comparison")
            if comparison:
                checkpoint = root / "checkpoint" / mode / stage
                comparison["score"] = scoring(item["baseline"], comparison["assessment"])
                if checkpoint.is_dir():
                    comparison["source"] = {name: artifact(checkpoint / name) for name in FILES if (checkpoint / name).is_file()}
            completed.append(item)
    post_host_architecture = []
    for lane in ("bl", "bl2"):
        path = root / "work" / lane / "modules" / "architecture.md"
        if path.is_file():
            post_host_architecture.append({"lane": lane, "snapshot": artifact(path)})
    return scrub({"run": root.name, "metadata": meta, "outcome": {"error": result.get("error"),
        "preflight": result.get("preflight"), "laneErrors": [row["error"] for row in result.get("lanes", []) if "error" in row]},
        "superseded": read(root / "superseded.json"), "stages": completed, "progress": events(root / "progress.jsonl"),
        "events": calls, "roleUsage": usage(calls), "roleUsageByWindow": {window: usage(calls, window)
            for window in ("comparison", "extension", "cleanup")}, "persistedReceipts": receipts(root),
        "postHostArchitecture": post_host_architecture,
        "persistedUsageOutsideWindow": read(root / "persisted-usage-outside-window.json", {})})


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("destination", type=Path)
    parser.add_argument("runs", nargs="*", type=Path)
    args = parser.parse_args()
    roots = args.runs or sorted(ROOT.glob("r-*"))
    roots = [path.resolve(strict=True) for path in roots]
    destination = args.destination.resolve()
    if not destination.is_relative_to(ROOT) or any(not path.is_relative_to(ROOT) for path in roots):
        raise SystemExit("Use the isolated G drive engineering QA folder.")
    fixture_names = ["SPEC.md", "CHANGE-G2.md", "METHOD.md", "assess.py", "base_assess.py", "hard_assess.py", "SPEC-G3.md", "CHANGE-G4.md", "fixture.mjs", "run.mjs", "witness.mjs",
                     "late-usage.mjs", "publish.py", "summary.py", "import-probe.py",
                     "review-probe.py", "probe.py", "python_syntax.py", "measure.py", "oracle-smoke.json", "postfreeze.py",
                     "grader_controls.py", "grader-controls.json", "oracle-0.7.25.json"]
    output = {"spec": "building-loop-engineering-three-arm-evidence/1",
              "fixtures": {name: artifact(ROOT / name) for name in fixture_names},
              "seed": {name: artifact(ROOT / "seed" / name) for name in FILES},
              "runs": [run(path) for path in roots]}
    loaded_witnesses = {hashlib.sha256(path.read_bytes()).hexdigest(): artifact(path)
                        for root in roots if (path := root / "h" / "profiles" / "qa" / "witness.mjs").is_file()}
    output["fixtures"]["loadedWitnesses"] = loaded_witnesses
    verification_path = destination.with_name(destination.name.removesuffix("-public.json") + "-verification.json")
    verification = read(verification_path)
    if verification and {path.name for path in roots} == set(verification["runIds"]):
        output["verification"] = verification
    design_path = destination.with_name(destination.name.removesuffix("-public.json") + "-design-verification.json")
    design = read(design_path)
    if design and {path.name for path in roots} == set(design["runs"]):
        output["fixtures"][design_path.name] = artifact(design_path)
    supplemental = {"f3435": ["f3435-rep3-no-defect-rejection.json", "handoff-pager-raw-compact.json",
                                "f3435-import-probe.json", "f3435-quality-probes.json"],
                    "b795": ["b795-rep1-false-review.json", "b795-rep1-repeated-false-review.json",
                              "b795-import-probe.json", "b795-quality-probes.json"],
                    "cdf0": ["cdf0-example-audit.json", "cdf0-quality-probes.json"],
                    "d8df": ["d8df-example-audit.json", "d8df-quality-probes.json"]}
    shas = [entry["metadata"].get("archiveSha256", "") for entry in output["runs"]]
    attachments = [name for tag, names in supplemental.items() if any(sha.startswith(tag) for sha in shas) for name in names]
    if attachments:
        output["supplementalEvidence"] = {name: artifact(ROOT / name) for name in attachments if (ROOT / name).is_file()}
    for cleanup_path in ROOT.glob("*-process-cleanup.json"):
        cleanup = read(cleanup_path, {})
        if {path.name for path in roots} == set(cleanup.get("runIds", [])):
            output["processCleanup"] = {key: item for key, item in cleanup.items() if key != "controllerPids"}
            break
    postfreeze = read(ROOT / "postfreeze-results.json")
    if postfreeze:
        assert {path.name for path in roots} == set(postfreeze['proofOfHostExit']['runIds'])
        postfreeze['proofOfHostExit'].pop('controllerPids', None)
        output['postfreeze'] = postfreeze
    encoded = json.dumps(scrub(output), ensure_ascii=False, indent=2) + "\n"
    for name in ("online.seed", "postfreeze.seed"):
        private = ROOT.parent / "private-grader" / name
        if private.is_file():
            value = private.read_text(encoding="ascii").strip()
            if not re.fullmatch(r"[0-9a-f]{32}", value) or value in encoded:
                raise ValueError("A private grader seed is invalid or present in the public bundle")
    destination.write_text(encoded, encoding="utf-8", newline="\n")

import-probe.py.text:
"""Compare the note's generated import section with independent Python AST."""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

from assess import architecture


ROOT = Path(__file__).resolve().parent
HEADING = re.compile(r"^## 静态导入\s*$(.*?)(?=^#{1,2} |\Z)", re.M | re.S)
ROW = re.compile(r'^("(?:[^"\\]|\\.)+") -> (.+)$')


def check(source):
    scan = architecture(source)
    expected = {name + ".py": sorted(dep + ".py" for dep in row["moduleImports"])
                for name, row in scan.items() if row.get("parse")}
    note = (source / "modules" / "architecture.md").read_text(encoding="utf-8")
    sections = HEADING.findall(note)
    if len(sections) != 1:
        return {"status": "missing" if not sections else "repeated", "expected": expected}
    body = sections[0].strip().splitlines()
    if not body or not body[0].startswith("```text") or body[-1] != "```":
        return {"status": "unstructured", "expected": expected}
    actual = {}
    for line in body[1:-1]:
        row = ROW.fullmatch(line)
        if not row:
            return {"status": "invalid-row", "expected": expected}
        path, imports = json.loads(row[1]), json.loads("[" + row[2] + "]") if row[2] != "[]" else []
        if path in actual:
            return {"status": "duplicate-row", "expected": expected}
        actual[path] = imports
    valid = len(expected) == len(scan) and actual == expected
    return {"status": "exact" if valid else "mismatch", "expected": expected, "observed": actual}


if __name__ == "__main__":
    observations = []
    for name in sys.argv[1:]:
        run = (ROOT / name).resolve(strict=True)
        if not run.is_relative_to(ROOT):
            raise SystemExit("Use only the isolated G QA root")
        for mode in ("standard", "building-loop"):
            for stage in ("g1", "g2"):
                for window in ("checkpoint", "frozen"):
                    source = run / window / mode / stage
                    if source.is_dir():
                        observations.append({"run": name, "mode": mode, "stage": stage, "window": window, **check(source)})
    print(json.dumps({"method": "Static direct import rows match independent Python AST; prose, dynamic imports and runtime behavior are assessed separately.",
        "observations": observations}, indent=2))

probe.py.text:
"""Run an owner-registered executable against one isolated source snapshot."""

from __future__ import annotations

import json
import math
import os
import re
import resource
import selectors
import signal
import stat
import subprocess
import sys
import tempfile
import time
from contextlib import ExitStack
from pathlib import Path, PurePosixPath

BWRAP = "/usr/bin/bwrap"
MAX_REQUEST = 64 * 1024
MAX_OUTPUT = 64 * 1024
PREVIEW = 2048
SNAPSHOT_BYTES = 4 * 1024 * 1024
SNAPSHOT_FILES = 256
MAX_FIXTURE_BYTES = 16 * 1024
UNSAFE_PATH = re.compile(r'[:*?"<>|\\\x00-\x1f\x7f\u202a-\u202e\u2066-\u2069]|[. ]$')
FRAME = re.compile(r'^  File "/submission/([^"\n]+)", line (\d{1,8}), in ([^\n]{1,80})$', re.M)
RESERVED = {"submission", "scratch", "tmp", "proc", "dev"}


def shape(row, fields):
    if type(row) is not dict or row.keys() - fields:
        raise ValueError("Unexpected fields")


def integer(value, low, high):
    if type(value) is not int or not low <= value <= high:
        raise ValueError("Integer outside configured bounds")
    return value


def flag(value):
    if type(value) is not bool:
        raise ValueError("Expected a boolean")
    return value


def bounded_text(value, maximum):
    if type(value) is not str or "\0" in value or len(value.encode("utf-8")) > maximum:
        raise ValueError("Invalid or oversized text")
    return value


def names(value, count, size):
    if type(value) is not list or len(value) > count:
        raise ValueError("Unexpected argument count")
    return [bounded_text(item, size) for item in value]


def relative_path(value):
    parts = bounded_text(value, 500).split("/")
    if any(not part or len(part.encode("utf-8")) > 240 or UNSAFE_PATH.search(part) for part in parts):
        raise ValueError("Expected an exact relative file path")
    return value


def sandbox_path(value):
    bounded_text(value, 240)
    if not value.startswith("/"):
        raise ValueError("Expected an absolute sandbox path")
    relative_path(value[1:])
    return value


def runtime_flags(mounts, links):
    flags, used = [], set()
    for field, rows in [("--ro-bind", mounts), ("--symlink", links)]:
        if type(rows) is not list or len(rows) > 16:
            raise ValueError("Invalid runtime recipe")
        for row in rows:
            shape(row, {"source", "target"})
            source, target = sandbox_path(row["source"]), sandbox_path(row["target"])
            if PurePosixPath(target).parts[1] in RESERVED or target in used:
                raise ValueError("Runtime mount overlaps a reserved sandbox path")
            used.add(target)
            if field == "--ro-bind":
                entry = Path(source).resolve(strict=True).stat()
                if not stat.S_ISDIR(entry.st_mode) and not stat.S_ISREG(entry.st_mode):
                    raise ValueError("Runtime mount is not a directory or regular file")
            flags.extend((field, source, target))
    return flags


def recipe_config(recipe):
    shape(recipe, {"executable", "entrypoint", "fixedArgs", "mounts", "links",
                   "maxArgs", "maxFiles", "allowStdin", "timeoutMs"})
    executable = sandbox_path(recipe["executable"])
    entrypoint = relative_path(recipe["entrypoint"]) if "entrypoint" in recipe else None
    fixed = names(recipe.get("fixedArgs", []), 24, 512)
    if entrypoint is not None:
        fixed.append("/submission/" + entrypoint)
    runtime = runtime_flags(recipe.get("mounts", []), recipe.get("links", []))
    return {
        "command": [executable, *fixed], "entrypoint": entrypoint, "runtime": runtime,
        "maxArgs": integer(recipe.get("maxArgs", 0), 0, 24),
        "maxFiles": integer(recipe.get("maxFiles", 0), 0, 12),
        "allowStdin": flag(recipe.get("allowStdin", False)),
        "timeoutMs": integer(recipe.get("timeoutMs", 4000), 100, 10000),
    }


def probe_input(request, config):
    shape(request, {"args", "stdin", "files"})
    argv = names(request.get("args", []), config["maxArgs"], 512)
    stdin = bounded_text(request.get("stdin", ""), 8192).encode("utf-8")
    if "stdin" in request and not config["allowStdin"]:
        raise ValueError("Probe does not accept stdin")
    files = request.get("files", [])
    if type(files) is not list or len(files) > config["maxFiles"]:
        raise ValueError("Unexpected scratch file count")
    contents = {}
    for row in files:
        shape(row, {"path", "content"})
        name = relative_path(bounded_text(row["path"], 160))
        if name in contents:
            raise ValueError("Duplicate scratch file")
        contents[name] = bounded_text(row["content"], MAX_FIXTURE_BYTES).encode("utf-8")
    if any(str(parent) in contents for name in contents for parent in PurePosixPath(name).parents):
        raise ValueError("A scratch file cannot also be a directory")
    if sum(map(len, contents.values())) > MAX_FIXTURE_BYTES:
        raise ValueError("Scratch inputs exceed the byte limit")
    return argv, stdin, contents


def snapshot_copy(source, target):
    """Copy exact regular files from an adapter-owned snapshot via directory FDs."""
    files, size, directories = {}, 0, 0
    root = os.open(source, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        def fail(error):
            raise error

        for parent, dirs, filenames, fd in os.fwalk(".", onerror=fail, follow_symlinks=False, dir_fd=root):
            directories += len(dirs)
            if directories > 4096:
                raise ValueError("Snapshot has too many directories")
            for directory in dirs:
                relative_path(PurePosixPath(parent, directory).as_posix())
                if not stat.S_ISDIR(os.stat(directory, dir_fd=fd, follow_symlinks=False).st_mode):
                    raise ValueError("Snapshot directories cannot be links")
            for filename in sorted(filenames):
                name = relative_path(PurePosixPath(parent, filename).as_posix())
                handle = os.open(filename, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=fd)
                with os.fdopen(handle, "rb") as stream:
                    entry = os.fstat(stream.fileno())
                    if not stat.S_ISREG(entry.st_mode) or entry.st_nlink != 1 or entry.st_size > SNAPSHOT_BYTES - size:
                        raise ValueError("Snapshot contains a linked, special or oversized file")
                    data = stream.read(SNAPSHOT_BYTES - size + 1)
                size += len(data)
                if len(files) >= SNAPSHOT_FILES or size > SNAPSHOT_BYTES:
                    raise ValueError("Snapshot exceeds the file or byte limit")
                output = target / name
                output.parent.mkdir(parents=True, exist_ok=True)
                output.write_bytes(data)
                output.chmod(entry.st_mode & 0o777)
                files[name] = data.count(b"\n") + int(bool(data) and not data.endswith(b"\n"))
    finally:
        os.close(root)
    return files


def sandbox_command(config, source, inputs, stack, status_file):
    command = [BWRAP, "--unshare-all", "--unshare-user", "--disable-userns", "--assert-userns-disabled",
               "--die-with-parent", "--new-session", "--cap-drop", "ALL", "--clearenv",
               "--ro-bind", str(source), "/submission", "--proc", "/proc", "--dev", "/dev",
               "--size", "8388608", "--tmpfs", "/scratch", "--symlink", "/scratch", "/tmp",
               "--setenv", "LANG", "C.UTF-8", "--setenv", "HOME", "/scratch",
               "--setenv", "TMPDIR", "/scratch", "--setenv", "PATH", "/usr/bin",
               "--chdir", "/scratch", "--json-status-fd", str(status_file.fileno()), *config["runtime"]]
    fds = [status_file.fileno()]
    for path, content in inputs.items():
        file = stack.enter_context(tempfile.TemporaryFile())
        file.write(content)
        file.seek(0)
        fds.append(file.fileno())
        command.extend(("--file", str(file.fileno()), "/scratch/" + path))
    return command, fds


def drain(process, stdin, deadline):
    """Keep both pipes drained under one wall-clock deadline and byte budget."""
    captured = {"stdout": bytearray(), "stderr": bytearray()}
    remaining = memoryview(stdin)
    with selectors.DefaultSelector() as selector:
        for name in captured:
            selector.register(getattr(process, name), selectors.EVENT_READ, name)
        if remaining:
            os.set_blocking(process.stdin.fileno(), False)
            selector.register(process.stdin, selectors.EVENT_WRITE, "stdin")
        else:
            process.stdin.close()
        while selector.get_map():
            timeout = deadline - time.monotonic()
            if timeout <= 0:
                return "timeout", captured
            for key, _ in selector.select(timeout):
                fd, name = key.fileobj.fileno(), key.data
                if name == "stdin":
                    try:
                        remaining = remaining[os.write(fd, remaining):]
                    except BrokenPipeError:
                        remaining = remaining[:0]
                    except BlockingIOError:
                        continue
                    if not remaining:
                        selector.unregister(key.fileobj)
                        key.fileobj.close()
                    continue
                available = MAX_OUTPUT - sum(map(len, captured.values()))
                chunk = os.read(fd, min(4096, available + 1))
                if not chunk:
                    selector.unregister(key.fileobj)
                    continue
                captured[name].extend(chunk[:available])
                if len(chunk) > available:
                    return "output-limit", captured
    try:
        process.wait(timeout=max(0, deadline - time.monotonic()))
    except subprocess.TimeoutExpired:
        return "timeout", captured
    return "exited", captured


def execute(config, source, inputs, argv, stdin):
    with ExitStack() as stack:
        status_file = stack.enter_context(tempfile.TemporaryFile())
        command, fds = sandbox_command(config, source, inputs, stack, status_file)
        cpu_seconds = math.ceil(config["timeoutMs"] / 1000) + 1

        def limits():
            # Bound per-process resources; bubblewrap isolates and reaps its PID namespace.
            resource.setrlimit(resource.RLIMIT_CPU, (cpu_seconds, cpu_seconds))
            resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
            resource.setrlimit(resource.RLIMIT_NOFILE, (256, 256))
            resource.setrlimit(resource.RLIMIT_FSIZE, (8 * 1024 * 1024, 8 * 1024 * 1024))
            resource.setrlimit(resource.RLIMIT_AS, (1024 ** 3, 1024 ** 3))
            resource.setrlimit(resource.RLIMIT_NPROC, (256, 256))

        process = stack.enter_context(subprocess.Popen([*command, "--", *config["command"], *argv],
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            pass_fds=tuple(fds), start_new_session=True, env={}, preexec_fn=limits))
        try:
            status, captured = drain(process, stdin, time.monotonic() + config["timeoutMs"] / 1000)
        finally:
            if process.poll() is None:
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
        status_file.seek(0)
        records = [json.loads(line) for line in status_file.read(8192).splitlines()]
        if not any(type(row.get("child-pid")) is int for row in records):
            return "unavailable", None, captured
        return status, process.returncode if status == "exited" else None, captured


def run(recipe, source, request):
    config = recipe_config(recipe)
    argv, stdin, inputs = probe_input(request, config)
    with tempfile.TemporaryDirectory(prefix="building-loop-probe-") as directory:
        snapshot = Path(directory, "source")
        snapshot.mkdir()
        files = snapshot_copy(Path(source), snapshot)
        if config["entrypoint"] is not None and config["entrypoint"] not in files:
            raise ValueError("Recipe entrypoint is absent from the snapshot")
        status, exit_code, captured = execute(config, snapshot, inputs, argv, stdin)
    stderr = captured["stderr"].decode("utf-8", errors="replace")
    frames = [
        {"path": path, "line": int(line), "function": function}
        for path, line, function in FRAME.findall(stderr)
        if path in files and 1 <= int(line) <= files[path]
        and re.fullmatch(r"[A-Za-z0-9_.<> -]+", function)
    ][-6:]
    previews = {key: value.decode("utf-8", errors="replace").encode("utf-8") for key, value in captured.items()}
    return {
        "status": status, "exitCode": exit_code,
        **{key: value[:PREVIEW].decode("utf-8", errors="ignore") for key, value in previews.items()},
        "frames": frames, "truncated": status == "output-limit" or any(len(value) > PREVIEW for value in previews.values()),
    }


def main():
    try:
        recipe_file, source = sys.argv[1:]
        with open(recipe_file, "rb") as file:
            recipe_bytes = file.read(MAX_REQUEST + 1)
        raw = sys.stdin.buffer.read(MAX_REQUEST + 1)
        if max(len(raw), len(recipe_bytes)) > MAX_REQUEST:
            raise ValueError("Request exceeds the byte limit")
        result = run(json.loads(recipe_bytes), source, json.loads(raw))
    except (OSError, ValueError, KeyError, subprocess.SubprocessError):
        result = {"status": "unavailable", "exitCode": None, "stdout": "", "stderr": "", "frames": [], "truncated": False}
    print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))


if __name__ == "__main__":
    main()

