                      for index, item in enumerate(requests)]
    except BatchItemError as exc:
        return batch_failure(str(exc), exc.index)

    # Phase 2: a repeated ID is a retry when the request data matches the first
    # occurrence and a conflict otherwise, reported at the later occurrence.
    first_seen = {}
    planned = []
    for index, (item, operation_id) in enumerate(zip(requests, operations)):
        fingerprint = request_fingerprint(item)
        seen = first_seen.get(operation_id)
        if seen is None:
            first_seen[operation_id] = (index, fingerprint)
            planned.append((index, item, operation_id))
        elif seen[1] != fingerprint:
            return batch_failure(CONFLICTING_OPERATION, index)

    # Phase 3: only new IDs are calculated, and the first real failure ends the
    # batch before the quota is ever considered.
    new_results = {}
    total = 0
    for index, item, operation_id in planned:
        try:
            # A batch item always rolls back: its own `action` is not accepted,
            # and the G2 plan quota never applies to any single rollback.
            actions, units = plan_item(item, ROLLBACK_ACTION)
        except (PolicyError, JournalError) as exc:
            return batch_failure(str(exc), index)
        new_results[index] = {"actions": actions, "units": units,
                              "operationId": operation_id}
        total += units

    # Phase 4: the limit covers the deduplicated batch, so a retried operation
    # is charged once. Equality is allowed.
    if total > request["limit"]:
        return batch_failure(BATCH_LIMIT_EXCEEDED, None)

    # A retry answers with its first occurrence's result, repeated in place.
    results = [dict(new_results[first_seen[operation_id][0]])
               for operation_id in operations]
    return {"status": "ok", "results": results, "units": total}

