    stack = list(retained)
    # The walk must cover the *whole* graph, not just applied nodes: c(applied,
    # retained) -> b(unapplied) -> a(applied) still needs a kept, so an
    # unapplied intermediate must be traversed through, only never kept itself.
    # This is an explicit stack rather than recursion so a 2,000-change
    # dependency chain cannot hit the interpreter recursion limit.
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in keep:
                continue
            if target in applied:
                keep.add(target)
            stack.append(target)
    return keep


