    if not isinstance(request, dict):
        return failure("invalid-request")
    result, code = _execute(request)
    if code is not None:
        return failure(code)
    return result


# G3 batch limits: at most this many independent rollback requests in one call.
MAX_BATCH_REQUESTS = 128
BATCH_FIELDS = frozenset({"action", "requests"})


def batch_failure(code, index):
    """Whole-batch failure: no partial results, no partial units."""
    return {
        "status": "error",
        "error": code,
        "requestIndex": index,
        "results": [],
        "units": 0,
    }


def plan_batch(request):
    """`rollback-many`: run each request independently, all-or-nothing.

    Top-level shape problems (extra fields, non-list `requests`, empty or more
    than 128 entries) are `invalid-batch` with a null index. An element that is
    not an object, or carries a field other than environment/budget/changes/
    applied/retain, is `invalid-batch-item` with its real 0-based index. Each
    surviving element is handed to the ordinary single-request path with
    `action` forced to rollback, and the first business failure stops the batch
    with its own code and index.

    Items share nothing: every element is copied, and planner keeps no module
    state between calls, so IDs, applied journals and retain sets never cross.
