        if code is not None:
            # Earlier results are discarded: a batch is one indivisible
            # operation, so a later failure must not leave a partial plan.
            return batch_failure(code, index)
        results.append({"actions": result["actions"], "units": result["units"]})
    return {
        "status": "ok",
        "results": results,
        "units": sum(result["units"] for result in results),
    }


def _first_bad_item(items):
    """Index of the first structurally invalid element; it is reported verbatim."""
    for index, item in enumerate(items):
        try:
            read_batch_item(item)
        except JournalError:
