def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    result, code = _execute(request)
    if code is not None:
        return failure(code)
    return result


# G3/G4 batch limits: at most this many independent rollback requests in one call.
MAX_BATCH_REQUESTS = 128
# G4 adds the mandatory `limit`; it stays in the allowed set (and is required)
# so that a caller still sending the G3 shape fails loudly instead of silently
# running with no ceiling.
BATCH_FIELDS = frozenset({"action", "limit", "requests"})


def batch_failure(code, index):
    """Whole-batch failure: no partial results, no partial units."""
    return {
        "status": "error",
        "error": code,
        "requestIndex": index,
        "results": [],
        "units": 0,
    }


def _canonical(value):
    """Order-insensitive-but-type-strict form of a JSON value, for retry equality.

    Only the *shape* of an object must stop mattering: two requests that differ
    merely in key order are the same request. Arrays keep their order, because
    `[a, b]` and `[b, a]` are different request data. JSON booleans and numbers
    must not collapse into each other (`1` vs `true`, `1` vs `1.0`), so the
    type tag is part of the key: `(0, True)` can never collide with `(3, 1)`.

    `item` never reaches the business path before this comparison, so only the
    already-validated element shape is expected; other JSON values still get a
    distinct, deterministic key so one element can never compare equal to a
    differently structured one.
    """
    if isinstance(value, dict):
        return ("object", tuple(sorted((key, _canonical(member))
                                       for key, member in value.items())))
    if isinstance(value, list):
        return ("array", tuple(_canonical(member) for member in value))
    if value is None:
        return ("null",)
    # type() keeps bool/int apart, which is the whole point of the check.
    return (type(value).__name__, value)


def plan_batch(request):
    """`rollback-many`: run each request independently, all-or-nothing.

    G4 order of decisions, all in the caller's original request order:

    1. Top-level shape (extra/missing fields, `limit` not a nonnegative int or
       a boolean, `requests` not a list or outside 1..128) is `invalid-batch`
       with a null index.
    2. Per element: structure and operation ID are settled first by
       `read_batch_item` (`invalid-batch-item` + real index), then the element's
       operation ID is looked up. A later element repeating an operation ID with
       equivalent data is a retry: it reuses the first result, is charged once,
       and still occupies its position. A later element repeating an operation
       ID with different data is `conflicting-operation` at that later index.
    3. Only a first-seen operation ID is executed through the same single-
       request path as plain rollback, so its business code stops the batch with
       its own index. That failure always wins over the batch `limit`.
    4. Only after every element has been processed is the summed units of the
       de-duplicated actions compared with `limit`: more is
       `batch-limit-exceeded` with a null index, equal or less commits.

    Items share nothing: every element is copied, each first-seen operation is
    computed independently, and planner keeps no module state between calls, so
    IDs, applied journals and retain sets never cross between elements.
    """
    if not isinstance(request, dict) or set(request) - BATCH_FIELDS:
        return batch_failure("invalid-batch", None)
    if "requests" not in request or "limit" not in request:
        return batch_failure("invalid-batch", None)
    # type() rather than isinstance() so a boolean limit never counts as an int.
    limit = request["limit"]
    if type(limit) is not int or limit < 0:
        return batch_failure("invalid-batch", None)
    items = request["requests"]
    if not isinstance(items, list) or not 1 <= len(items) <= MAX_BATCH_REQUESTS:
        return batch_failure("invalid-batch", None)
    seen = {}
    results = []
    total = 0
    for index, item in enumerate(items):
        try:
            operation_id = read_operation_id(item)
            validated = read_batch_item(item)
        except JournalError as exc:
            return batch_failure(str(exc), index)
        # The operation ID is compared on its own; the request data decides
        # retry versus conflict. Both are needed to see a difference.
        canonical = _canonical(validated)
        first = seen.get(operation_id)
        if first is not None:
            if first[0] != canonical:
                # Same ID, different payload: the caller reused an ID for two
                # different operations, which cannot be resolved by retrying.
                return batch_failure("conflicting-operation", index)
            # Retry: reuse the stored result, charge nothing extra.
            result = first[1]
        else:
            result, code = _execute(validated)
            if code is not None:
                # Earlier results are discarded: a batch is one indivisible
                # operation, so a later failure must not leave a partial plan.
                # This is checked before the limit on purpose.
                return batch_failure(code, index)
            result = {"actions": result["actions"], "units": result["units"]}
            seen[operation_id] = (canonical, result)
            total += result["units"]
        results.append({
            "actions": list(result["actions"]),
            "units": result["units"],
            "operationId": operation_id,
        })
    if total > limit:
        # Batch-only ceiling: plain rollback is still uncapped by the G2 quota.
        return batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": total}

