"""Compose policy and journal data into a plan."""
import heapq
import json

from journal import JournalError, read_changes, read_request_applied, read_retain
from policy import (BATCH_ITEM_FIELDS, MAX_OPERATION_ID, PolicyError,
                    batch_requests, is_batch, limit_for)


def failure(code, request_index=None):
    """The single-object error shape; a batch failure adds `requestIndex`."""
    result = {"status": "error", "error": code, "actions": [], "units": 0}
    if request_index is not None:
        result["requestIndex"] = request_index
    return result


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. An unapplied dependency is not installed and so is never kept, but the
    walk continues through it: c -> b(unapplied) -> a still keeps a when c is
    retained, because a is installed and c still needs it.

    The walk is iterative because a batch item may carry 2,000+ changes, and a
    dependency chain that deep would exhaust Python's recursion limit. Every
    change is visited at most once -- only a kept ID is pushed -- and the graph
    is acyclic by the time this runs, so two retained IDs whose closures meet
    converge instead of looping.
    """
    keep = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in applied and target not in keep:
                keep.add(target)
                stack.append(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def actions_for(policy, request):
    """Emit action IDs and their total units for one validated request.

    Graph and journal work only; policy has already decided what may run and
    how far a plan's budget reaches. Returning units from here keeps the single
    and batch entrypoints from disagreeing about the accounting.
    """
    changes = read_changes(request.get("changes"))
    applied = read_request_applied(request)
    by_id = build_graph(changes)
    if not applied <= by_id.keys():
        raise JournalError("unknown-dependency")
    order = topological_order(by_id)
    if policy.action == "rollback":
        retained = read_retain(request, applied)
        actions = rollback_actions(by_id, order, applied, retained)
        return actions, sum(by_id[key]["units"] for key in actions)
    actions = [key for key in order if key not in applied]
    units = sum(by_id[key]["units"] for key in actions)
    if units > policy.limit:
        raise PolicyError("budget-exceeded")
    return actions, units


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    if is_batch(request):
        return plan_batch(request)
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        actions, units = actions_for(policy, request)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}


def read_batch_item(item):
    """Add the batch-imposed rollback action to one item, rejecting bad shapes.

    The envelope check cannot do this: whether an item is an object, and which
    fields it carries, is an item-level fact. A present `action` of any value is
    rejected because the field is not allowed; anything else would silently
    accept a `plan` request dressed as a rollback.

    G4: `operation_id` is required and must be a nonempty string of at most
    MAX_OPERATION_ID characters. It is compared verbatim (no case folding or
    trimming), and it is checked here -- with the rest of the single-item
    structure, before any duplicate/conflict or G2 work -- so a malformed item
    reports `invalid-batch-item` at its own index even when it repeats an
    earlier operation.
    """
    if not isinstance(item, dict):
        raise PolicyError("invalid-batch-item")
    if frozenset(item) - BATCH_ITEM_FIELDS:
        raise PolicyError("invalid-batch-item")
    operation_id = item.get("operation_id")
    if (not isinstance(operation_id, str) or not operation_id
            or len(operation_id) > MAX_OPERATION_ID):
        raise PolicyError("invalid-batch-item")
    request = dict(item)
    request["action"] = "rollback"
    return request


def canonical(value):
    """An order-insensitive-for-objects, order-preserving-for-arrays key.

    Two items are equivalent exactly when their canonical forms are equal: an
    object's field order does not matter (dicts are sorted by key), an array's
    order does (arrays stay arrays), and JSON numbers and booleans never mix
    (`true` is not `1`, `1` is not `1.0`). `json.dumps` then fixes a total,
    type-tagged representation for hashing.
    """
    if isinstance(value, dict):
        return {key: canonical(value[key]) for key in sorted(value)}
    if isinstance(value, list):
        return [canonical(entry) for entry in value]
    return value


def operation_key(request):
    """The full request data of an item, minus its own identity fields.

    `operation_id` identifies the operation, not the work; `action` is
    batch-imposed and identical for every item. What remains -- environment,
    budget, changes, applied, retain -- is the request data G4 compares.
    """
    data = {key: value for key, value in request.items()
            if key not in ("operation_id", "action")}
    return json.dumps(canonical(data), sort_keys=True, separators=(",", ":"))


def plan_batch(request):
    """Run ordered, deduplicated rollbacks under one batch limit.

    Items are planned one at a time in request order and results are buffered,
    so a failure in item k emits no results at all and reports item k's own
    error code with its index. Every item builds its own graph and journal;
    nothing -- IDs, applied records, retain sets -- crosses distinct operations.

    G4 processing order, per item: (1) item structure and operation ID, then
    (2) duplicate or conflict against the operation ID. An operation ID already
    seen with identical request data is a retry: it emits no new result and is
    not counted. The same ID with different data is `conflicting-operation` at
    this index. Only (3) a new ID runs the item's G2 validation and
    computation. The first actual item failure therefore wins over the batch
    limit, which is checked once at the end against the deduplicated units.
    """
    try:
        items, limit = batch_requests(request)
    except PolicyError as exc:
        return failure(str(exc), None)
    results = []
    total = 0
    # operation_id -> canonical request data, populated only by items that
    # passed their own G2 validation and computation.
    accepted = {}
    for index, item in enumerate(items):
        try:
            request_item = read_batch_item(item)
            operation_id = request_item["operation_id"]
            key = operation_key(request_item)
            seen = accepted.get(operation_id)
            if seen is not None:
                if seen != key:
                    raise PolicyError("conflicting-operation")
                continue
            policy = limit_for(request_item)
            actions, units = actions_for(policy, request_item)
        except (PolicyError, JournalError) as exc:
            return failure(str(exc), index)
        accepted[operation_id] = key
        results.append({"operationId": operation_id, "actions": actions, "units": units})
        total += units
    if total > limit:
        return failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": total}

