    computation. The first actual item failure therefore wins over the batch
    limit, which is checked once at the end against the deduplicated units.
    """
    try:
        items, limit = batch_requests(request)
    except PolicyError as exc:
        return failure(str(exc), None)
    results = []
    total = 0
    # operation_id -> canonical request data, populated only by items that
    # passed their own G2 validation and computation.
    accepted = {}
    for index, item in enumerate(items):
        try:
            request_item = read_batch_item(item)
            operation_id = request_item["operation_id"]
            key = operation_key(request_item)
            seen = accepted.get(operation_id)
            if seen is not None:
                if seen != key:
                    raise PolicyError("conflicting-operation")
                continue
            policy = limit_for(request_item)
            actions, units = actions_for(policy, request_item)
        except (PolicyError, JournalError) as exc:
            return failure(str(exc), index)
        accepted[operation_id] = key
        results.append({"operationId": operation_id, "actions": actions, "units": units})
        total += units
    if total > limit:
        return failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": total}

